import{_ as a,o as t,a as r,a2 as o}from"./chunks/framework.DCcmcJcL.js";const g=JSON.parse('{"title":"Before You Start","description":"","frontmatter":{},"headers":[],"relativePath":"getting-started/before-you-start.md","filePath":"getting-started/before-you-start.md","lastUpdated":1789319767000}'),n={name:"getting-started/before-you-start.md"};function i(s,e,l,d,c,h){return t(),r("div",null,e[0]||(e[0]=[o(`<h1 id="before-you-start" tabindex="-1">Before You Start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before You Start&quot;">​</a></h1><p>Welcome to the Bagisto development journey! This guide will help you prepare your development environment and understand the foundational knowledge needed to work effectively with Bagisto, a powerful Laravel-based e-commerce platform.</p><p>Whether you&#39;re planning to customize an existing store, build new features, or contribute to the community, having the right setup and background knowledge will set you up for success.</p><h2 id="getting-ready-for-bagisto" tabindex="-1">Getting Ready for Bagisto <a class="header-anchor" href="#getting-ready-for-bagisto" aria-label="Permalink to &quot;Getting Ready for Bagisto&quot;">​</a></h2><p>To work efficiently with Bagisto (especially the latest versions), having a basic understanding of certain concepts will help you learn faster and customize with confidence.</p><h3 id="🐘-php-basics-and-best-practices" tabindex="-1">🐘 PHP Basics and Best Practices <a class="header-anchor" href="#🐘-php-basics-and-best-practices" aria-label="Permalink to &quot;🐘 PHP Basics and Best Practices&quot;">​</a></h3><ul><li><a href="https://www.php.net/manual/en/langref.php" target="_blank" rel="noreferrer">Core PHP concepts</a>: variables, functions, arrays, and control structures</li><li><a href="https://www.php.net/manual/en/language.namespaces.php" target="_blank" rel="noreferrer">Namespaces</a> and <a href="https://www.php.net/manual/en/language.oop5.autoload.php" target="_blank" rel="noreferrer">how autoloading works</a></li><li><a href="https://www.php-fig.org/psr/psr-4/" target="_blank" rel="noreferrer">PSR-4 autoloading guidelines</a></li><li><a href="https://www.php.net/manual/en/language.oop5.php" target="_blank" rel="noreferrer">Object-Oriented Programming (OOP) in PHP</a></li><li><a href="https://getcomposer.org/doc/01-basic-usage.md" target="_blank" rel="noreferrer">Using Composer to manage dependencies</a></li></ul><h3 id="⚡-key-laravel-knowledge-for-bagisto" tabindex="-1">⚡ Key Laravel Knowledge for Bagisto <a class="header-anchor" href="#⚡-key-laravel-knowledge-for-bagisto" aria-label="Permalink to &quot;⚡ Key Laravel Knowledge for Bagisto&quot;">​</a></h3><ul><li><a href="https://laravel.com/docs/routing" target="_blank" rel="noreferrer">Defining routes</a> and <a href="https://laravel.com/docs/controllers" target="_blank" rel="noreferrer">building controllers</a></li><li>Understanding the <a href="https://laravel.com/docs/container" target="_blank" rel="noreferrer">Service Container</a> and <a href="https://laravel.com/docs/providers" target="_blank" rel="noreferrer">Dependency Injection</a></li><li><a href="https://laravel.com/docs/middleware" target="_blank" rel="noreferrer">Middleware</a> and the request-handling flow</li><li><a href="https://laravel.com/docs/events" target="_blank" rel="noreferrer">Events</a>, <a href="https://laravel.com/docs/events#defining-listeners" target="_blank" rel="noreferrer">listeners</a>, and <a href="https://laravel.com/docs/eloquent#observers" target="_blank" rel="noreferrer">model observers</a></li><li>Working with <a href="https://laravel.com/docs/eloquent" target="_blank" rel="noreferrer">Eloquent ORM</a> and <a href="https://laravel.com/docs/migrations" target="_blank" rel="noreferrer">database migrations</a></li><li><a href="https://laravel.com/docs/blade" target="_blank" rel="noreferrer">Blade templating essentials</a></li></ul><p>Bagisto 2.4 runs on Laravel 12; the current development version runs on Laravel 13. The concepts above are the same on both.</p><h3 id="🎨-helpful-extras-for-advanced-customization" tabindex="-1">🎨 Helpful Extras for Advanced Customization <a class="header-anchor" href="#🎨-helpful-extras-for-advanced-customization" aria-label="Permalink to &quot;🎨 Helpful Extras for Advanced Customization&quot;">​</a></h3><ul><li><a href="https://tailwindcss.com/docs/installation" target="_blank" rel="noreferrer">Tailwind CSS</a> for modern, responsive styling (version 4 on the current development version, version 3 on Bagisto 2.4)</li><li><a href="https://vuejs.org/guide/introduction.html" target="_blank" rel="noreferrer">Vue.js basics</a> for interactive features</li><li>Asset bundling with <a href="https://laravel.com/docs/vite" target="_blank" rel="noreferrer">Vite</a></li><li><a href="https://laravel.com/docs/packages" target="_blank" rel="noreferrer">Creating custom Laravel packages</a></li></ul><h3 id="🔗-learn-and-connect" tabindex="-1">🔗 Learn and Connect <a class="header-anchor" href="#🔗-learn-and-connect" aria-label="Permalink to &quot;🔗 Learn and Connect&quot;">​</a></h3><ul><li><a href="https://github.com/bagisto/bagisto" target="_blank" rel="noreferrer">Bagisto GitHub Repository</a> – Browse code, report issues, and contribute</li><li><a href="https://forums.bagisto.com/" target="_blank" rel="noreferrer">Bagisto Forums</a> – Ask questions and join community discussions</li></ul><div class="tip custom-block"><p class="custom-block-title">💡 Pro Tip</p><p>You can start with Bagisto even as a beginner, but familiarity with Laravel and Vue.js will make your development process much smoother.</p></div><h2 id="system-requirements" tabindex="-1">System Requirements <a class="header-anchor" href="#system-requirements" aria-label="Permalink to &quot;System Requirements&quot;">​</a></h2><p>Before diving into Bagisto development, ensure your system meets these requirements:</p><h3 id="🖥️-server-configuration" tabindex="-1">🖥️ Server Configuration <a class="header-anchor" href="#🖥️-server-configuration" aria-label="Permalink to &quot;🖥️ Server Configuration&quot;">​</a></h3><ul><li><strong>Server</strong>: Apache 2, NGINX or OpenLiteSpeed</li><li><strong>RAM</strong>: 4GB or higher</li><li><strong>Node</strong>: 22 LTS or higher (needed only to build front-end assets and to run the Playwright tests)</li><li><strong>PHP</strong>: 8.4 for the current development version; 8.3 or 8.4 for Bagisto 2.4. PHP 8.5 and above are not supported yet</li><li><strong>Composer</strong>: 2.5 or higher</li></ul><h3 id="🧩-php-extensions" tabindex="-1">🧩 PHP Extensions <a class="header-anchor" href="#🧩-php-extensions" aria-label="Permalink to &quot;🧩 PHP Extensions&quot;">​</a></h3><p><code>composer.json</code> requires <code>calendar</code>, <code>curl</code>, <code>intl</code>, <code>mbstring</code>, <code>openssl</code>, <code>pdo</code>, <code>pdo_mysql</code> and <code>tokenizer</code>. The installer additionally checks for <code>ctype</code>, <code>dom</code>, <code>fileinfo</code>, <code>filter</code>, <code>gd</code>, <code>hash</code>, <code>json</code>, <code>pcre</code>, <code>session</code> and <code>xml</code>.</p><ul><li><strong>php-intl</strong>: Required for internationalization support</li><li><strong>php-gd</strong> (or <strong>php-imagick</strong>): Image processing; the driver is chosen with <code>IMAGE_DRIVER</code> on the current development version</li><li><strong>php-pdo_pgsql</strong>: Only when running on PostgreSQL</li><li><strong>Other standard Laravel extensions</strong>: Check via <code>php -m</code> command</li></ul><h3 id="⚙️-php-configuration" tabindex="-1">⚙️ PHP Configuration <a class="header-anchor" href="#⚙️-php-configuration" aria-label="Permalink to &quot;⚙️ PHP Configuration&quot;">​</a></h3><p>Key settings in your <code>php.ini</code>:</p><div class="language-ini vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ini</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">memory_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 4G</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">max_execution_time</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 360</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">date.timezone</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Asia/Kolkata  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Change to your timezone</span></span></code></pre></div><h3 id="🗄️-database" tabindex="-1">🗄️ Database <a class="header-anchor" href="#🗄️-database" aria-label="Permalink to &quot;🗄️ Database&quot;">​</a></h3><p>Bagisto is tested on three engines, and each is a first-class choice:</p><table tabindex="0"><thead><tr><th>Engine</th><th>Version</th><th>Availability</th></tr></thead><tbody><tr><td><strong>MySQL</strong></td><td>8.0</td><td>Bagisto 2.4 and the current development version</td></tr><tr><td><strong>MariaDB</strong></td><td>10.11</td><td>Bagisto 2.4 and the current development version</td></tr><tr><td><strong>PostgreSQL</strong></td><td>16</td><td>Current development version</td></tr></tbody></table><ul><li><strong>Collation</strong>: <code>utf8mb4_unicode_ci</code> on MySQL and MariaDB (recommended)</li><li>The installer asks which engine to use and fills in the default port. See <a href="./../advanced/database-compatibility.html">Database compatibility</a> for what to keep in mind when writing code that must run on all three.</li></ul><h3 id="🔍-optional-services" tabindex="-1">🔍 Optional services <a class="header-anchor" href="#🔍-optional-services" aria-label="Permalink to &quot;🔍 Optional services&quot;">​</a></h3><ul><li><strong>Elasticsearch 8.x</strong> for catalog search on larger stores; see <a href="./../performance/configure-elasticsearch.html">Configure Elasticsearch</a></li><li><strong>Redis</strong> for the cache, session, queue and full page cache stores in production</li><li><strong>Amazon S3 or Cloudflare R2</strong> for media on the current development version; see <a href="./../advanced/file-storage.html">File Storage</a></li></ul><div class="tip custom-block"><p class="custom-block-title">Quick Check</p><p>Run <code>php -v</code> and <code>composer --version</code> to verify your PHP and Composer versions meet the requirements.</p></div>`,32)]))}const u=a(n,[["render",i]]);export{g as __pageData,u as default};
